mapper.select:
select id from litemall_goods
where source = 'cj' and cj_pid = #{cjPid}
limit 1

select brand_id as brandId, count(*) as goodsCount from litemall_goods where deleted = 0 and is_on_sale = 1 and brand_id in
#{bid}
group by brand_id

mapper.update:
update litemall_goods
set cj_reviews_ingested_time = now()
where id = #{goodsId}
